WITH sales_agg AS (SELECT ib.ib_income_band_sk, ib.ib_lower_bound, ib.ib_upper_bound, SUM(ss.ss_net_profit) AS total_profit, SUM(ss.ss_ext_sales_price) AS total_sales, COUNT(DISTINCT ss.ss_customer_sk) AS distinct_customers FROM store_sales ss JOIN household_demographics hd ON ss.ss_hdemo_sk = hd.hd_demo_sk JOIN income_band ib ON hd.hd_income_band_sk = ib.ib_income_band_sk GROUP BY ib.ib_income_band_sk, ib.ib_lower_bound, ib.ib_upper_bound), returns_agg AS (SELECT ib.ib_income_band_sk, ib.ib_lower_bound, ib.ib_upper_bound, SUM(sr.sr_return_amt) AS total_return_amount, SUM(sr.sr_return_quantity) AS total_return_qty FROM store_returns sr JOIN household_demographics hd ON sr.sr_hdemo_sk = hd.hd_demo_sk JOIN income_band ib ON hd.hd_income_band_sk = ib.ib_income_band_sk GROUP BY ib.ib_income_band_sk, ib.ib_lower_bound, ib.ib_upper_bound) SELECT s.ib_income_band_sk, s.ib_lower_bound, s.ib_upper_bound, s.total_profit, s.total_sales, s.distinct_customers, COALESCE(r.total_return_amount, 0) AS total_return_amount, COALESCE(r.total_return_qty, 0) AS total_return_qty, CASE WHEN s.total_profit > 100000 THEN 'High' WHEN s.total_profit > 50000 THEN 'Medium' ELSE 'Low' END AS profit_category, RANK() OVER (ORDER BY s.total_profit DESC) AS profit_rank FROM sales_agg s LEFT JOIN returns_agg r ON s.ib_income_band_sk = r.ib_income_band_sk ORDER BY profit_rank
